message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure, limitation, or unavailability identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure, tool unavailability, or capability limitation.",
      "target_description": "A subsequent agent action intended to overcome that failure or limitation."
    },
    {
      "name": "USES_OBSERVED_DATA_AS_INPUT",
      "definition": "A subsequent agent action consumes data, identifiers, or resource references obtained from an earlier observation as an input argument or operation target.",
      "source_description": "An earlier observation that supplies data or identifiers required for a task.",
      "target_description": "A subsequent action that uses the observed data or identifiers as inputs."
    },
    {
      "name": "SCALES_UP_AFTER_SUCCESSFUL_PROBE",
      "definition": "A prior probe action successfully demonstrates that a required capability or access method works, and a subsequent action scales that method to a bulk operation.",
      "source_description": "A successful small-scale probe or capability check.",
      "target_description": "A subsequent larger-scale action that relies on the verified capability."
    },
    {
      "name": "EXTRACTS_REQUIRED_DATA_FROM_OBSERVED_RESOURCE",
      "definition": "From an earlier observation of a file or data resource, the agent identifies and extracts specific information required for the task.",
      "source_description": "An observation containing a resource with relevant embedded data.",
      "target_description": "An agent inference or extracted value selecting the task-relevant data from that observation."
    },
    {
      "name": "IDENTIFIES_COMPONENT_FROM_TASK_CONSTRAINT",
      "definition": "An agent interprets a task specification or constraint, such as a molecule representation or binding requirement, to determine which protein or component must be used.",
      "source_description": "A task specification or constraint that describes a required property.",
      "target_description": "An agent decision or inference identifying a matching component for the construct."
    },
    {
      "name": "PLANS_FROM_OBSERVED_INFORMATION",
      "definition": "An agent formulates a plan or next-step strategy based on information gathered from earlier observations.",
      "source_description": "Observed information relevant to the task.",
      "target_description": "An agent plan or decision specifying subsequent actions."
    }
  ]
}

